// 对串做一次从左到右的平衡字母变换
string apply_once(string s) {
    int n = (int)s.size();
    array<int, 26> freq{}, left{};
    for (char ch : s) ++freq[ch - 'a'];
    for (int i = 0; i < n; ++i) {
        int c = s[i] - 'a';
        if (left[c] == freq[c] - left[c] - 1) {
            --freq[c];
            int nc = (c + 1) % 26;
            s[i] = char('a' + nc);
            ++freq[nc];
            ++left[nc];
        } else ++left[c];
    }
    return s;
}

int main() {
